let prevMouseX = 0;
let prevMouseY = 0;
let explosionX;
let explosionY;
let r;

class ExplosionManager {

  constructor () {
    this.explosions = []; 
  }

  add (x, y, h) {
    this.explosions.push(new Explosion(x,y,h));
  }

  draw () {
    // loop through explosions[] and draw each one
    // check if w/h of explosion is bigger than canvas and delete
    for (let i=this.explosions.length-1; i>=0; i--) {
      this.explosions[i].draw();
      if (this.explosions[i].r > width*4) {
        this.explosions.splice(i, 1);
      }
    }
  }
}

class Explosion {

  // x,y  coords
  // p    particles
  // h    hue
  constructor(x, y, h){

    // public
    this.x = x
    this.y = y
    this.h = h;
    this.r = 0;

    // private
    this.p = 20;
    this.angle = 0;
  }

  draw () {
    this.r += 25;

    //convert polar coordinates to cartesian coordinates

    for (let ring = 1; ring<5; ring++) {
      let ring_radius = this.r * (ring*0.25);

      for (let a = 0; a<=this.p; a++){
        var x = ring_radius * sin(this.angle);
        var y = ring_radius * cos(this.angle);

        //draw ellipse at every x,y point
        stroke(color(this.h, 255, 255));
        strokeWeight(50);
        ellipse(this.x+x, this.y+y, 5);

        //increase angle by step size
        this.angle = a*(TWO_PI/this.p);
      }  
    }

  } 
}

const explosionManager = new ExplosionManager();

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 255);
  background(0);

  describe('When the mouse is moved, a rainbow trails behind it. When the mouse is clicked, a colorful firework-like explosion expands radially from the mouse position.');
}

// line history
const historySize = 50;
let lineHistory = [];

function addLineHistory(x1, y1, x2, y2, hue) {
  let newLine = { 
    x1: x1, 
    y1: y1, 
    x2: x2, 
    y2: y2, 
    hue: hue
  };  

  // add line to history queue
  lineHistory.unshift(newLine);

  if (lineHistory.length == historySize+1) {
    lineHistory.splice(historySize, 1);
  }
}

function lineHistoryErode() {
  lineHistory.splice(lineHistory.length-1, 1);
//   for (let i=0; i<lineHistory.length; i++) {
//     lineHistory[i].hue
//   }
}

// hue variables
let hueValue = 0;
let hueOffset = 1;

function draw() {

  if (hueValue > 255 || hueValue < 0) {
    hueOffset = -hueOffset;
  } 

  // change hue only when mouse position changes
  if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) != prevMouseX || (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) != prevMouseY){
    hueValue += hueOffset;

    // populate line history
    addLineHistory((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), prevMouseX, prevMouseY, hueValue);
  } else {
    lineHistoryErode();
  }

  // Draw history
  background(0);

  //strokeWeight(30);
  noFill();

  for (let i=lineHistory.length - 1; i>0; i--) {

    let h = lineHistory[i].hue;
    let s = 255;
    let b = 255 - ((i / lineHistory.length) * 255);

    strokeWeight(50 - ((i / lineHistory.length) * 50));
    stroke(color(h,s,b));

    beginShape();
    vertex(lineHistory[i].x1, lineHistory[i].y1);
    vertex(lineHistory[i].x2, lineHistory[i].y2);
    endShape();
  }

  // store for next frame  
  prevMouseX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
  prevMouseY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

  explosionManager.draw();

}

function mousePressed() {
  explosionManager.add((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), hueValue);
}

